insert into public.permission_catalog(key,domain,name,description,module,action,scopes,dependencies)
values('backoffice.functions.cockpit_reports_query','tenant','Managementrapportage lezen','Actuele kerncijfers en vaste rapportversies binnen bestaande dossier-, financiële en HR-rechten.','reports','read',array['tenant'],array['backoffice.access','backoffice.reports.read','backoffice.followup.read','backoffice.functions.cockpit_followup']),
 ('backoffice.functions.cockpit_reports_command','tenant','Managementrapport samenstellen','Een onveranderlijke rapportversie vastleggen; alleen de huidige eigenaar kan rapportplanning wijzigen.','reports','write',array['tenant'],array['backoffice.functions.cockpit_reports_query']) on conflict(key) do nothing;
insert into private.management_role_permissions(tenant_id,role_id,capability)
select r.tenant_id,r.id,c.key from private.management_roles r join public.permission_catalog c on c.key in('backoffice.functions.cockpit_reports_query','backoffice.functions.cockpit_reports_command') where r.code='owner' or exists(select 1 from private.management_role_permissions p where p.role_id=r.id and p.capability='backoffice.reports.read') on conflict do nothing;
insert into public.notification_catalog(code,name,description,category,module,status,contexts,channels,default_channels,recipient_description,variables,tenant_override)
values('management.report.ready','Managementrapport beschikbaar','Een geplande, geautoriseerde momentopname is gereed. De melding bevat uitsluitend een privélink.','Managementrapportage','rapportage','active',array['backoffice'],array['in_app','email'],array['in_app','email'],'Actieve ontvangers uit de door de eigenaar ingestelde doelgroep',array['bedrijfsnaam','rapportperiode'],true) on conflict(code) do nothing;
insert into private.notification_templates(tenant_id,type_code,context,channel,draft)
select null,'management.report.ready','backoffice',ch,jsonb_build_object('title','Managementrapport {rapportperiode} staat klaar','body','Je wekelijkse rapport bij {bedrijfsnaam} is beschikbaar. Open de beveiligde rapportversie om de toegestane cijfers te bekijken.','cta_label','Bekijk het rapport') from unnest(array['in_app','email'])ch where not exists(select 1 from private.notification_templates t where t.tenant_id is null and t.type_code='management.report.ready' and t.context='backoffice' and t.channel=ch);
insert into private.notification_template_versions(template_id,revision,definition) select t.id,1,t.draft from private.notification_templates t where t.type_code='management.report.ready' and t.tenant_id is null and not exists(select 1 from private.notification_template_versions v where v.template_id=t.id and v.revision=1);
update private.notification_templates t set active_version_id=v.id from private.notification_template_versions v where v.template_id=t.id and t.type_code='management.report.ready' and t.tenant_id is null and v.revision=1 and t.active_version_id is null;
notify pgrst,'reload schema';
